#include "MapGenerator.h"

#include <string>
#include <sstream>

// Sets default values
AMapGenerator::AMapGenerator() {
	// Set this actor to call Tick() every frame.  You can turn this off to improve performance if you don't need it.
	PrimaryActorTick.bCanEverTick = true;
}

// Called when the game starts or when spawned
void AMapGenerator::BeginPlay() {
	Super::BeginPlay();
	Generate();
}

// Called every frame
void AMapGenerator::Tick(float DeltaTime) {
	Super::Tick(DeltaTime);
}

void AMapGenerator::Generate() {
	std::istringstream stream(AMapGenerator::_data[Level]);
	std::vector<std::string> lines;
	std::string line;

	while (std::getline(stream, line, '*')) {
		lines.push_back(line);
	}

	int rows = lines.size();
	int cols = lines.empty() ? 0 : lines[0].size();

	int halfRows = rows / 2;
	int halfCols = cols / 2;

	for (int rowIdx = 0; rowIdx < rows; ++rowIdx) {
		for (int colIdx = 0; colIdx < lines[rowIdx].size(); ++colIdx) {
			float posX = (colIdx - halfCols) * 100;
			float posY = (rowIdx - halfRows) * 100;
			int value = lines[rowIdx][colIdx] - '0';
			if (value == 1) {
				if (WallFactory) {
					AWall* wall = GetWorld()->SpawnActor<AWall>(WallFactory, FVector(0, posX, posY), FRotator(0, 0, 0));
				}
				else {
					UE_LOG(LogTemp, Error, TEXT("WallFactory is NULL!"));
				}
			}
		}
	}
}


